/**
 * HeroVideo.tsx — generated by make_hero_video.py
 *
 * Place the generated assets in your /public folder:
 *     public/hero.webm
 *     public/hero.mp4
 *     public/hero-poster.webp
 *
 * Then preload the poster in your page/layout <head> for the best LCP:
 *
 *   // app/layout.tsx (or a <Head> in pages router)
 *   <link rel="preload" as="image" href="/hero-poster.webp" />
 *
 * The component skips the video on mobile / data-saver / slow connections
 * and shows the poster image instead.
 */
'use client'

import { useEffect, useState } from 'react'

export default function HeroVideo({
  children,
}: {
  children?: React.ReactNode
}) {
  const [showVideo, setShowVideo] = useState(false)

  useEffect(() => {
    const conn = (navigator as any).connection
    const isMobile = window.matchMedia('(max-width: 767px)').matches
    const slow =
      conn?.saveData === true ||
      ['slow-2g', '2g'].includes(conn?.effectiveType)
    const reducedMotion = window.matchMedia(
      '(prefers-reduced-motion: reduce)'
    ).matches

    if (!isMobile && !slow && !reducedMotion) setShowVideo(true)
  }, [])

  return (
    <section className="relative h-screen w-full overflow-hidden">
      {showVideo ? (
        <video
          autoPlay
          muted
          loop
          playsInline
          poster="/hero-poster.webp"
          preload="metadata"
          className="absolute inset-0 h-full w-full object-cover"
        >
          <source src="/hero.webm" type="video/webm" />
          <source src="/hero.mp4" type="video/mp4" />
        </video>
      ) : (
        <img
          src="/hero-poster.webp"
          alt=""
          aria-hidden="true"
          className="absolute inset-0 h-full w-full object-cover"
        />
      )}

      {/* Darkening overlay for text legibility */}
      <div className="absolute inset-0 bg-black/40" />

      {/* Foreground content */}
      <div className="relative z-10 flex h-full items-center justify-center text-center text-white">
        {children ?? <h1 className="text-5xl font-bold">Your headline</h1>}
      </div>
    </section>
  )
}
